package security

import (
	"bytes"
	"encoding/hex"
	"errors"
	"strings"
	"sync"
	"testing"
)

// Literal vectors were calculated independently with Node's standard SHA256 and
// HMAC primitives: PRK=HMAC(rawName, token), T1=HMAC(PRK, info || 0x01).
// They are not generated by NetworkContext or Go's crypto/hkdf implementation.
func TestNetworkContextIndependentVectors(t *testing.T) {
	vectors := []struct {
		name, cidr, token, descriptor, id, psk, prologue string
	}{
		{
			name: "mesh-a", cidr: "10.30.0.0/24", token: "0123456789abcdef0123456789abcdef",
			descriptor: "73696d706c65746965722d76312f6e6574776f726b2d636f6e74657874000000066d6573682d610000000c31302e33302e302e302f3234",
			id:         "c5af1c1cac81ccc9af97f836b3462087e909221ca550dfb42e57cac022db37c6",
			psk:        "0bb5fbb64399da6aac97b849567412d088cf789f477b5dbae41bd18c18da670c",
			prologue:   "73696d706c65746965722d76312f70726f6c6f6775650000001273696d706c65746965722d76312f6c696e6b0000003773696d706c65746965722d76312f6e6574776f726b2d636f6e74657874000000066d6573682d610000000c31302e33302e302e302f3234000000040001feff",
		},
		{
			name: " Mesh-\u00e9 ", cidr: "192.0.2.0/31", token: "fixture-token-two",
			descriptor: "73696d706c65746965722d76312f6e6574776f726b2d636f6e7465787400000009204d6573682dc3a9200000000c3139322e302e322e302f3331",
			id:         "663dc559c7decd0e16c8714c487a7a3cfadc936499ea055e2f068d59fe02d129",
			psk:        "143ff52941a7ea285dbdd0c7a0f47e4510b931f60a89139daf5bf57038f2a757",
			prologue:   "73696d706c65746965722d76312f70726f6c6f6775650000001273696d706c65746965722d76312f6c696e6b0000003a73696d706c65746965722d76312f6e6574776f726b2d636f6e7465787400000009204d6573682dc3a9200000000c3139322e302e322e302f3331000000040001feff",
		},
	}
	for _, v := range vectors {
		t.Run(v.name, func(t *testing.T) {
			ctx, err := NewNetworkContext(v.name, v.cidr)
			if err != nil {
				t.Fatal(err)
			}
			if got := hex.EncodeToString(ctx.Descriptor()); got != v.descriptor {
				t.Fatalf("descriptor=%s, want %s", got, v.descriptor)
			}
			id := ctx.ID()
			if got := hex.EncodeToString(id[:]); got != v.id {
				t.Fatalf("ContextID=%s, want %s", got, v.id)
			}
			psk, err := ctx.DerivePSK(v.token)
			if err != nil {
				t.Fatal(err)
			}
			if hex.EncodeToString(psk[:]) != v.psk {
				t.Fatal("PSK does not match independent project HKDF vector")
			}
			prologue, err := ctx.Prologue("simpletier-v1/link", []byte{0, 1, 254, 255})
			if err != nil || hex.EncodeToString(prologue) != v.prologue {
				t.Fatalf("prologue=%x, error=%v; want %s", prologue, err, v.prologue)
			}
		})
	}
}

func TestNetworkContextWireIDIndependentVectors(t *testing.T) {
	// Calculated independently with Node SHA256 over the frozen legacy byte string.
	for _, v := range []struct {
		name, cidr string
		want       uint64
	}{
		{"mesh-a", "10.30.0.0/24", 0x95678609d624abc7},
		{" Mesh-\u00e9 ", "192.0.2.0/31", 0xac69ad159cc837ab},
		{"mesh-a", "10.31.0.0/24", 0x9804561132783860},
	} {
		ctx, err := NewNetworkContext(v.name, v.cidr)
		if err != nil {
			t.Fatal(err)
		}
		if ctx.WireID() != v.want {
			t.Fatalf("wire locator=%016x, want %016x", ctx.WireID(), v.want)
		}
		if ctx.ID() == ([32]byte{}) {
			t.Fatal("locator replaced the full context ID")
		}
		before := ctx.WireID()
		if _, err := ctx.DerivePSK("rotated-fixture-token"); err != nil {
			t.Fatal(err)
		}
		if ctx.WireID() != before {
			t.Fatal("token rotation changed public locator")
		}
	}
	var zero NetworkContext
	if zero.WireID() != 0 {
		t.Fatal("zero context has a fabricated locator")
	}
}

func TestNetworkContextSeparatesLiteralNameCIDRAndToken(t *testing.T) {
	base, err := NewNetworkContext("mesh-a", "10.30.0.0/24")
	if err != nil {
		t.Fatal(err)
	}
	basePSK, err := base.DerivePSK("fixture-token")
	if err != nil {
		t.Fatal(err)
	}
	for _, v := range []struct{ name, cidr string }{
		{"mesh-a ", "10.30.0.0/24"},
		{" mesh-a", "10.30.0.0/24"},
		{"MESH-A", "10.30.0.0/24"},
		{"mesh-a", "10.30.1.0/24"},
		{"mesh-a", "10.30.0.0/25"},
		{"${NETWORK_NAME}", "10.30.0.0/24"},
	} {
		ctx, err := NewNetworkContext(v.name, v.cidr)
		if err != nil {
			t.Fatal(err)
		}
		psk, err := ctx.DerivePSK("fixture-token")
		if err != nil {
			t.Fatal(err)
		}
		if ctx.ID() == base.ID() || psk == basePSK || bytes.Equal(ctx.Descriptor(), base.Descriptor()) {
			t.Fatalf("distinct literal network context collapsed: %q %q", v.name, v.cidr)
		}
	}
	rotated, err := base.DerivePSK("rotated-fixture-token")
	if err != nil || rotated == basePSK {
		t.Fatal("token rotation did not change PSK")
	}
	unchanged, err := NewNetworkContext("mesh-a", "10.30.0.0/24")
	if err != nil || unchanged.ID() != base.ID() || !bytes.Equal(unchanged.Descriptor(), base.Descriptor()) {
		t.Fatal("public context changed independently of its name/CIDR")
	}
	// Token is opaque nonempty material, not a Unicode identifier or expanded config.
	for _, token := range []string{" ${TOKEN} ", string([]byte{0xff, 0, 1})} {
		if _, err := base.DerivePSK(token); err != nil {
			t.Fatal("opaque nonempty token rejected:", err)
		}
	}
}

func TestNetworkContextPreservesUnicodeNormalizationAndWhitespace(t *testing.T) {
	contexts := []NetworkContext{}
	for _, name := range []string{"\u00e9", "e\u0301", " ", " \u00e9 "} {
		ctx, err := NewNetworkContext(name, "192.0.2.9/32")
		if err != nil {
			t.Fatal(err)
		}
		for _, prior := range contexts {
			if prior.ID() == ctx.ID() || bytes.Equal(prior.Descriptor(), ctx.Descriptor()) {
				t.Fatal("Unicode or whitespace was normalized")
			}
		}
		contexts = append(contexts, ctx)
	}
}

func TestNetworkContextRejectsInvalidInputsWithoutLeakingValues(t *testing.T) {
	for _, name := range []string{"", "PRIVATE-NAME\x00VALUE", string([]byte{0xff})} {
		if _, err := NewNetworkContext(name, "10.30.0.0/24"); !errors.Is(err, ErrInvalidNetworkContext) || strings.Contains(err.Error(), "PRIVATE-NAME") {
			t.Fatalf("invalid name error=%v", err)
		}
	}
	for _, cidr := range []string{"", "10.30.0.1/24", "10.30.0.0/0", "10.30.0.0/33", "010.30.0.0/24", "10.30.0.0/024", "10.30.0.0/24 ", " 10.30.0.0/24", "fd00::/64", "::ffff:192.0.2.0/120", "PRIVATE-CIDR"} {
		if _, err := NewNetworkContext("mesh-a", cidr); !errors.Is(err, ErrInvalidNetworkContext) || strings.Contains(err.Error(), "PRIVATE-CIDR") {
			t.Fatalf("invalid CIDR %q error=%v", cidr, err)
		}
	}
	for _, cidr := range []string{"0.0.0.0/1", "192.0.2.0/31", "192.0.2.9/32"} {
		if _, err := NewNetworkContext("mesh-a", cidr); err != nil {
			t.Fatalf("canonical CIDR rejected %q: %v", cidr, err)
		}
	}
	ctx, err := NewNetworkContext("mesh-a", "10.30.0.0/24")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := ctx.DerivePSK(""); !errors.Is(err, ErrInvalidNetworkContext) {
		t.Fatalf("empty token=%v", err)
	}
	for _, domain := range []string{"", "PRIVATE-DOMAIN\x00VALUE", string([]byte{0xff})} {
		if _, err := ctx.Prologue(domain, nil); !errors.Is(err, ErrInvalidNetworkContext) || strings.Contains(err.Error(), "PRIVATE-DOMAIN") {
			t.Fatalf("invalid domain=%v", err)
		}
	}
}

func TestNetworkContextZeroValueFailsClosed(t *testing.T) {
	var ctx NetworkContext
	if ctx.Descriptor() != nil || ctx.ID() != ([32]byte{}) {
		t.Fatal("zero context looks initialized")
	}
	const secret = "PRIVATE-TOKEN-MATERIAL"
	if _, err := ctx.DerivePSK(secret); !errors.Is(err, ErrInvalidNetworkContext) || strings.Contains(err.Error(), secret) {
		t.Fatalf("zero context DerivePSK error=%v", err)
	}
	if _, err := ctx.Prologue("simpletier-v1/link", nil); !errors.Is(err, ErrInvalidNetworkContext) {
		t.Fatalf("zero context Prologue error=%v", err)
	}
}

func TestNetworkContextCopyOwnershipAndDomainBinding(t *testing.T) {
	ctx, err := NewNetworkContext("mesh-a", "10.30.0.0/24")
	if err != nil {
		t.Fatal(err)
	}
	id := ctx.ID()
	original := ctx.Descriptor()
	mutated := ctx.Descriptor()
	mutated[0] ^= 0xff
	if !bytes.Equal(original, ctx.Descriptor()) || ctx.ID() != id {
		t.Fatal("descriptor accessor aliases internal state")
	}
	binding := []byte{1, 2, 3}
	prologue, err := ctx.Prologue("simpletier-v1/link", binding)
	if err != nil {
		t.Fatal(err)
	}
	pinned := append([]byte(nil), prologue...)
	binding[0] = 99
	prologue[0] ^= 0xff
	again, err := ctx.Prologue("simpletier-v1/link", []byte{1, 2, 3})
	if err != nil || !bytes.Equal(again, pinned) || ctx.ID() != id {
		t.Fatal("prologue/input binding aliases state")
	}
	for _, v := range []struct {
		domain  string
		binding []byte
	}{
		{"simpletier-v1/session", []byte{1, 2, 3}},
		{"SimpleTier-v1/link", []byte{1, 2, 3}},
		{"simpletier-v1/link", []byte{1, 2, 4}},
	} {
		other, err := ctx.Prologue(v.domain, v.binding)
		if err != nil || bytes.Equal(other, pinned) {
			t.Fatal("domain or binding was not separated")
		}
	}
	first, err := ctx.Prologue("ab", []byte("c"))
	if err != nil {
		t.Fatal(err)
	}
	second, err := ctx.Prologue("a", []byte("bc"))
	if err != nil || bytes.Equal(first, second) {
		t.Fatal("domain/binding length prefix is ambiguous")
	}
	copyOfContext := ctx
	if copyOfContext.ID() != id || !bytes.Equal(copyOfContext.Descriptor(), original) {
		t.Fatal("context value copy changed public identity")
	}
}

func TestNetworkContextConcurrentReadersAndDerivation(t *testing.T) {
	ctx, err := NewNetworkContext("mesh-a", "10.30.0.0/24")
	if err != nil {
		t.Fatal(err)
	}
	want, err := ctx.DerivePSK("fixture-token")
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	for range 32 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 20 {
				got, err := ctx.DerivePSK("fixture-token")
				if err != nil || got != want {
					t.Error("concurrent PSK mismatch")
				}
				d := ctx.Descriptor()
				d[0] ^= 0xff
				p, err := ctx.Prologue("simpletier-v1/link", nil)
				if err != nil || len(p) == 0 {
					t.Error("concurrent prologue failure")
				}
			}
		}()
	}
	wg.Wait()
}
